%macro randsamp(n);
%do i = 1 %to &n. ;
data all5&i;
set all5;
original_order+1;
*seed=&sysrandom ;
rand = rand('Uniform');
run;
proc sort data=all5&i(keep=analystzip analystid yrqtr)
out=round&i(rename=(analystid=pseudo_analystid));
  by analystzip rand;
run;
 data nall5&i;
  merge round&i all5&i;
  drop rand;
run;
proc sort data=nall5&i out=nround&i(drop=original_order);
  by original_order;
run;
proc sql;
create table final&i as
select a.analystzip, a.pseudo_analystid, a.analystid, a.yrqtr, a.chpi,
a.fsize,a.ior,a.retvol,a.bm,a.nanalysts,a.nrevs,
a.horizon, a.star, a.portsize, a.ivy, a.tenure, a.exp, a.cohort, a.firstemp, b.errors, b.bias
from nround&i as a, all5&i as b
where a.analystzip=b.analystzip and a.pseudo_analystid=b.analystid;
run;
%end;
%mend randsamp;
%randsamp(2);
%macro regression(n);
%do j = 1 %to &n. ;
%If &j. = 1 %then %do;
%clstr(data=final&j., dependent=errors, var= chpi fsize ior retvol bm nanalysts nrevs
horizon star portsize ivy tenure exp cohort firstemp, fe=empcbsa yrqtr, cluster=gvkey analystid);
%end;
%If &j. ne 1 %then %do;
%clstr(data=final&j., dependent=errors, var= chpi fsize ior retvol bm nanalysts nrevs

horizon star portsize ivy tenure exp cohort firstemp, fe=empcbsa yrqtr, cluster=gvkey analystid);
%end;
%end;
%mend regression;
%regression(2);

%macro append(n);
%do j = 1 %to &n. ;
%If &j.=1 %then %do;
data all; set final&j._est_cl; keep parameter estimate StdErr_or_cl1; run;
%end;
%If &j. ne 1 %then %do;
data final&j._est_cl; set final&j._est_cl; keep parameter estimate StdErr_or_cl1; run;
proc append base=all data=Final&j._est_cl; run;
%end;
%end;
%mend append;
